# Compare two inverse-variance pooling assumptions for the adjusted anti-TNF
# treatment-by-signature interactions generated by 28_trial_mechanism_interactions.R.
library(data.table)
source("config.R")
source("scripts/helpers.R")
setDTthreads(1L)

trial_dir <- file.path(DIR_RESULTS, "review_clinical_trials")
trials <- fread(file.path(trial_dir, "trial_models.csv"))
anti_tnf <- trials[model == "adjusted_complete" & trial %in% c("ACT-1", "PURSUIT-SC")]
primary <- fread(file.path(trial_dir, "pooled_models.csv"))[
  model == "adjusted_complete" & pool == "anti_TNF"]

stopifnot(nrow(anti_tnf) == 14L, nrow(primary) == 7L,
          all(is.finite(anti_tnf$log_or)), all(anti_tnf$se > 0),
          all(anti_tnf[trial == "ACT-1", n] == 44L),
          all(anti_tnf[trial == "PURSUIT-SC", n] == 87L),
          all(anti_tnf[, uniqueN(trial), by = signature_id]$V1 == 2L))

sensitivity <- anti_tnf[, {
  dl <- random_effects_meta(log_or, se)
  weights <- 1 / se^2
  common_log_or <- weighted.mean(log_or, weights)
  common_se <- sqrt(1 / sum(weights))
  list(k = .N, n = sum(n), dl_or = dl$or, dl_ci_low = dl$ci_low,
       dl_ci_high = dl$ci_high, dl_p = dl$p_value, dl_tau2 = dl$tau2,
       common_or = exp(common_log_or),
       common_ci_low = exp(common_log_or - 1.96 * common_se),
       common_ci_high = exp(common_log_or + 1.96 * common_se),
       common_p = 2 * pnorm(-abs(common_log_or / common_se)))
}, by = signature_id]

# Adjust the seven signature tests separately for each pooling method.
sensitivity[, dl_fdr := p.adjust(dl_p, method = "BH")]
sensitivity[, common_fdr := p.adjust(common_p, method = "BH")]
setcolorder(sensitivity, c("signature_id", "k", "n", "dl_tau2", "dl_or",
  "dl_ci_low", "dl_ci_high", "dl_p", "dl_fdr", "common_or", "common_ci_low",
  "common_ci_high", "common_p", "common_fdr"))

# Verify that all reconstructed random-effects results match Table 2B.
primary <- primary[match(sensitivity$signature_id, signature_id)]
check_cols <- c(or = "dl_or", ci_low = "dl_ci_low", ci_high = "dl_ci_high",
                p_value = "dl_p", fdr = "dl_fdr", tau2 = "dl_tau2")
for (primary_name in names(check_cols)) {
  stopifnot(isTRUE(all.equal(primary[[primary_name]], sensitivity[[check_cols[[primary_name]]]],
                             tolerance = 1e-10)))
}

output_dir <- file.path(DIR_RESULTS, "review_pool_sensitivity")
dir.create(output_dir, showWarnings = FALSE)
fwrite(sensitivity, file.path(output_dir, "antitnf_pool_comparison.csv"))
